cat > /app/output/styles.css << 'EOF'
:root {
  --bg: #f5f5f7;
  --bg-2: #ffffff;
  --text: #1d1d1f;
  --muted: #6e6e73;
  --accent: #0066cc;
  --line: #d2d2d7;
  --radius: 20px;
  --radius-sm: 12px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { width: min(1200px, 92vw); margin: 0 auto; }
.top-nav {
  position: sticky; top: 0; z-index: 50;
  background: rgba(245,245,247,0.92); backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}
.nav-inner { display: flex; align-items: center; gap: 24px; min-height: 52px; overflow-x: auto; }
.brand { font-weight: 700; letter-spacing: 0.2px; color: var(--text); }
.nav-links { display: flex; gap: 18px; white-space: nowrap; font-size: 14px; }
.announcement { background:#fff; border-bottom:1px solid var(--line); font-size:13px; color:var(--muted); }
.announcement .container { padding:10px 0; text-align:center; }
.hero { padding: 56px 0 28px; }
.hero h1 { font-size: clamp(40px, 6vw, 56px); line-height: 1.05; margin: 0 0 12px; }
.hero p { color: var(--muted); font-size: clamp(18px, 2.2vw, 24px); margin: 0; }
.section { padding: 28px 0; }
.section h2 { font-size: clamp(28px, 4.8vw, 48px); margin: 0 0 6px; }
.section .sub { color: var(--muted); margin: 0 0 18px; font-size: 18px; }
.product-bar { display:flex; gap:12px; overflow:auto; padding-bottom:6px; }
.product-pill {
  min-width:120px; background:#fff; border:1px solid var(--line); border-radius:16px;
  padding:14px 12px; text-align:center; font-size:13px;
}
.product-pill .icon { font-size:22px; display:block; margin-bottom:8px; }
.carousel-wrap { position: relative; }
.carousel {
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(260px, 1fr);
  gap: 18px; overflow-x: auto; padding: 6px 6px 12px; scroll-behavior: smooth;
}
.carousel::-webkit-scrollbar, .product-bar::-webkit-scrollbar, .tab-list::-webkit-scrollbar, .quick-links::-webkit-scrollbar, .section-nav-inner::-webkit-scrollbar { height: 10px; }
.carousel::-webkit-scrollbar-thumb, .product-bar::-webkit-scrollbar-thumb, .tab-list::-webkit-scrollbar-thumb, .quick-links::-webkit-scrollbar-thumb, .section-nav-inner::-webkit-scrollbar-thumb { background:#c7c7cc; border-radius:10px; }
.card {
  background: #fff; border-radius: var(--radius); border: 1px solid #ececf0;
  box-shadow: var(--shadow); min-height: 340px; overflow:hidden;
}
.card-media {
  height: 180px; display:flex; align-items:center; justify-content:center;
  font-size: 64px; font-weight:700;
}
.grad-blue { background: linear-gradient(135deg, #eaf4ff, #d9ebff); }
.grad-purple { background: linear-gradient(135deg, #f2edff, #e9defe); }
.grad-warm { background: linear-gradient(135deg, #fff3e9, #ffe7d8); }
.grad-cool { background: linear-gradient(135deg, #ebf8f8, #dff3f5); }
.card-body { padding: 18px; }
.eyebrow { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }
.card h3 { margin: 6px 0 8px; font-size: 24px; }
.card p { margin: 0 0 10px; color: var(--muted); }
.price { margin-top: auto; font-weight: 600; }
.finance { font-size:13px; color:var(--muted); }
.cta-row { display:flex; gap:14px; flex-wrap:wrap; font-size:14px; }
.arrow {
  position:absolute; top:50%; transform:translateY(-50%); z-index:2;
  width:40px; height:40px; border:none; border-radius:999px;
  background:rgba(29,29,31,0.88); color:#fff; cursor:pointer;
}
.arrow.left { left:-10px; }
.arrow.right { right:-10px; }
.grid-hero {
  display:grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap:16px;
}
.hero-tile {
  min-height: 460px; border-radius: var(--radius); overflow:hidden; background:#fff; border:1px solid #ececf0;
  display:flex; flex-direction:column; justify-content:space-between;
}
.hero-copy { padding:28px; }
.hero-copy h3 { font-size:34px; margin:0 0 8px; }
.hero-copy p { margin:0 0 12px; color:var(--muted); font-size:18px; }
.hero-actions { display:flex; gap:12px; flex-wrap:wrap; }
.btn { border-radius:999px; padding:10px 16px; font-size:14px; border:1px solid var(--accent); }
.btn.primary { background:var(--accent); color:#fff; }
.btn.secondary { color:var(--accent); background:transparent; }
.tab-list { display:flex; gap:10px; overflow:auto; margin-bottom:14px; }
.tab-btn {
  border:1px solid var(--line); background:#fff; border-radius:999px; padding:8px 14px; cursor:pointer;
}
.tab-btn.active { background:#1d1d1f; color:#fff; border-color:#1d1d1f; }
.tab-panel { display:none; }
.tab-panel.active { display:block; }
.section-nav {
  position: sticky; top: 52px; z-index: 40; background: rgba(245,245,247,0.95);
  border-top:1px solid var(--line); border-bottom:1px solid var(--line);
}
.section-nav-inner { display:flex; gap:18px; overflow:auto; white-space:nowrap; padding:10px 0; }
.quick-links { display:flex; gap:12px; overflow:auto; }
.quick-link { background:#fff; border:1px solid var(--line); border-radius:999px; padding:10px 14px; white-space:nowrap; }
footer { margin-top:36px; border-top:1px solid var(--line); background:#fff; }
.footer-grid { display:grid; grid-template-columns: repeat(5,1fr); gap:18px; padding:24px 0 30px; }
.footer-col h4 { font-size:14px; margin:0 0 8px; }
.footer-col a { display:block; color:var(--muted); margin:6px 0; font-size:13px; }
.footer-accordion { display:none; }
@media (max-width: 900px){
  .grid-hero { grid-template-columns: 1fr; }
  .arrow { display:none; }
  .footer-grid { grid-template-columns: repeat(2,1fr); }
}
@media (max-width: 720px){
  .hero { padding-top:34px; }
  .section-nav { top: 52px; }
  .footer-grid { display:none; }
  .footer-accordion { display:block; padding: 14px 0 28px; }
  .acc-item { border-bottom:1px solid var(--line); }
  .acc-btn {
    width:100%; text-align:left; background:none; border:none; padding:14px 0; font-weight:600;
    display:flex; justify-content:space-between; align-items:center;
  }
  .acc-panel { display:none; padding:0 0 10px; }
  .acc-panel a { display:block; color:var(--muted); margin:6px 0; font-size:13px; }
  .acc-item.open .acc-panel { display:block; }
}
EOF

cat > /app/output/main.js << 'EOF'
function setupCarousels() {
  document.querySelectorAll('[data-carousel]').forEach((wrap) => {
    const track = wrap.querySelector('.carousel');
    const prev = wrap.querySelector('[data-dir="prev"]');
    const next = wrap.querySelector('[data-dir="next"]');
    if (!track) return;
    const step = () => Math.max(280, Math.floor(track.clientWidth * 0.9));
    prev?.addEventListener('click', () => track.scrollBy({ left: -step(), behavior: 'smooth' }));
    next?.addEventListener('click', () => track.scrollBy({ left: step(), behavior: 'smooth' }));
  });
}

function setupTabs() {
  const tabGroups = document.querySelectorAll('[data-tabs]');
  tabGroups.forEach((group) => {
    const buttons = group.querySelectorAll('[role="tab"]');
    const panels = group.querySelectorAll('[role="tabpanel"]');
    buttons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const target = btn.getAttribute('data-target');
        buttons.forEach((b) => b.classList.toggle('active', b === btn));
        panels.forEach((p) => p.classList.toggle('active', p.id === target));
      });
    });
  });
}

function setupFooterAccordion() {
  document.querySelectorAll('.acc-btn').forEach((btn) => {
    btn.addEventListener('click', () => btn.parentElement.classList.toggle('open'));
  });
}

document.addEventListener('DOMContentLoaded', () => {
  setupCarousels();
  setupTabs();
  setupFooterAccordion();
});
EOF

